PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (telegram_id TEXT PRIMARY KEY, username TEXT, display_name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin','operator')), balance_vnd INTEGER NOT NULL DEFAULT 0 CHECK (balance_vnd >= 0), vip_level INTEGER NOT NULL DEFAULT 0 CHECK (vip_level >= 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (setting_key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_by TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, price_vnd INTEGER NOT NULL CHECK (price_vnd >= 0), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','hidden','archived')), metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL REFERENCES users(telegram_id), package_id TEXT NOT NULL REFERENCES packages(id), quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0), total_vnd INTEGER NOT NULL CHECK (total_vnd >= 0), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','rejected','cancelled')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deposits (id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL REFERENCES users(telegram_id), amount_vnd INTEGER NOT NULL CHECK (amount_vnd > 0), reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), reviewed_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS linked_accounts (id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL REFERENCES users(telegram_id), provider TEXT NOT NULL, account_name TEXT NOT NULL, secret_ciphertext TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (telegram_id, provider, account_name));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_user_created ON orders(telegram_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_deposits_status ON deposits(status);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);